import numpy as np
from scipy.optimize import least_squares
T=df['t'].values; PP=df['P'].values; Y=df['dP_dt'].values
ff={'t^a':lambda t,a: t**a,'exp(-at)':lambda t,a: np.exp(-a*t),'cos(at)':lambda t,a: np.cos(a*t),'sin(at)':lambda t,a: np.sin(a*t),'1/(t+a)':lambda t,a: 1/(t+a),'exp(a t)':lambda t,a: np.exp(a*t),'(1+at)':lambda t,a:1+a*t}
