    def res(p):
        w,a,b=p
        X=np.column_stack([1/PP,np.sin(w*PP)*T,f(T,a)*PP**b])
        c,_,_,_=np.linalg.lstsq(X,Y,rcond=None)
        return Y-X@c
    best=None
    for w0 in [0.5,0.6,0.7]:
        for a0 in [-0.5,0.1,0.5,1.5]:
            for b0 in [0.5,1.0,2.0]:
                try:
                    s=least_squares(res,[w0,a0,b0])
                except Exception: continue
                if best is None or s.cost<best.cost: best=s
    results.append((float(np.mean(best.fun**2)/np.var(Y)),fk,np.round(best.x,5)))
results.sort(key=lambda z:z[0])
